/* 回到顶部按钮：根据页面布局选择 #main 或 window 作为滚动容器 */
(function () {
	'use strict';

	function initBackToTop() {
		var main = document.getElementById('main');
		var nav = document.getElementById('topnav');
		var spacer = document.getElementById('nav-spacer');
		var copyright = document.getElementById('copyright');
		if (!main || document.getElementById('back-to-top')) {
			return;
		}

		function syncNavSpacer() {
			var navHeight = nav ? nav.offsetHeight : 56;
			var copyrightHeight = copyright ? copyright.offsetHeight : 0;
			if (nav && spacer) {
				spacer.style.height = navHeight + 'px';
			}
			if (document.documentElement.style.setProperty) {
				document.documentElement.style.setProperty('--nav-used-height', navHeight + 'px');
				document.documentElement.style.setProperty('--copyright-used-height', copyrightHeight + 'px');
			}
			main.style.maxHeight = Math.max(120, window.innerHeight - navHeight - copyrightHeight - 5) + 'px';
		}

		var button = document.createElement('button');
		button.id = 'back-to-top';
		button.type = 'button';
		button.setAttribute('aria-label', '回到顶部');
		button.title = '回到顶部';
		button.innerHTML = '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 11 7-7 7 7"></path><path d="M12 4v16"></path></svg>';
		document.body.appendChild(button);

		function getScrollTop() {
			return main.scrollTop;
		}

		function updateVisibility() {
			button.classList.toggle('is-visible', getScrollTop() > 160);
		}

		button.addEventListener('click', function () {
			// 平滑滚动：现代浏览器使用原生 smooth，不支持时回退为直接置顶
			if (typeof main.scrollTo === 'function') {
				try {
					main.scrollTo({ top: 0, behavior: 'smooth' });
					return;
				} catch (e) { /* 某些旧浏览器传对象会抛错，回退到下面的直接赋值 */ }
			}
			main.scrollTop = 0;
		});

		var framePending = false;
		var requestFrame = window.requestAnimationFrame || function (callback) {
			return window.setTimeout(callback, 16);
		};
		function scheduleVisibilityUpdate() {
			if (framePending) {
				return;
			}
			framePending = true;
			requestFrame(function () {
				framePending = false;
				updateVisibility();
			});
		}

		main.addEventListener('scroll', scheduleVisibilityUpdate, { passive: true });
		window.addEventListener('resize', function () {
			syncNavSpacer();
			scheduleVisibilityUpdate();
		});
		syncNavSpacer();
		updateVisibility();
	}

	if (document.readyState === 'loading') {
		document.addEventListener('DOMContentLoaded', initBackToTop);
	} else {
		initBackToTop();
	}
})();

